import json, glob, os
import numpy as np
from PIL import Image

def load_ours():
    im = Image.open('/private/var/folders/kp/vdv61pd97vd0x29b257r8h7h0000gn/T/barcode-gwb_6rhk/barcode.png').convert('RGB')
    a = np.asarray(im).astype(float)
    lum = 0.2126*a[:,:,0] + 0.7152*a[:,:,1] + 0.0722*a[:,:,2]
    return lum.mean(axis=0)

def resample(vals, W=1000):
    x = np.linspace(0, len(vals)-1, W)
    xi = np.arange(len(vals))
    return np.interp(x, xi, vals)

def segmeans(v, n):
    return np.array([s.mean() for s in np.array_split(v, n)])

def corr(a, b):
    if np.std(a) == 0 or np.std(b) == 0: return 0.0
    return float(np.corrcoef(a, b)[0, 1])

def score(ours, cand_times, cand_rgb, label=""):
    T = cand_times[-1]
    # normalized time -> index in ours (0..999)
    idx = np.clip((np.asarray(cand_times) / T) * 999, 0, 999)
    rgb = np.asarray(cand_rgb)
    luma = 0.2126*rgb[:,0] + 0.7152*rgb[:,1] + 0.0722*rgb[:,2]
    # candidate profile sampled at 1000 points (use nearest frame bins)
    prof = np.zeros(1000)
    counts = np.zeros(1000)
    for i, v in zip(idx.astype(int), luma):
        prof[i] += v; counts[i] += 1
    nz = counts > 0
    prof[nz] /= counts[nz]
    # fill gaps
    for i in range(1000):
        if not nz[i]:
            prof[i] = prof[max(0,i-1)] if nz[max(0,i-1)] else prof[min(999,i+1)]
    best = (-1, 0)
    for shift in range(-50, 51, 5):
        c = corr(ours, np.roll(prof, shift))
        if c > best[0]: best = (c, shift)
    c50 = max(corr(segmeans(ours,50), segmeans(np.roll(prof,s),50)) for s in range(-25,26,5))
    # trimmed (drop 3% each end)
    c_trim = corr(ours[30:970], prof[30:970])
    return dict(label=label, full=best[0], shift=best[1], seg50=c50, trim=c_trim, mean=prof.mean())

if __name__ == '__main__':
    ours = load_ours()
    files = sorted(glob.glob('/private/var/folders/kp/vdv61pd97vd0x29b257r8h7h0000gn/T/opencode/sb/*.json'))
    rows = []
    for f in files:
        data = json.load(open(f))
        t = [d[0] for d in data]; rgb = [d[1:] for d in data]
        label = os.path.basename(f).replace('.json','')
        rows.append(score(ours, t, rgb, label))
    rows.sort(key=lambda r: -r['full'])
    print(f"{'label':44s} {'full':>6} {'shift':>5} {'seg50':>6} {'trim':>6} {'mean':>6}")
    for r in rows:
        print(f"{r['label']:44s} {r['full']:6.3f} {r['shift']:5d} {r['seg50']:6.3f} {r['trim']:6.3f} {r['mean']:6.1f}")
